<!doctype html>
<html lang="en"><head><meta charset="utf-8"><title>{{ $invoice->invoice_number }}</title><script src="https://cdn.tailwindcss.com"></script><style>@media print{.no-print{display:none}}</style></head><body class="bg-white text-sm text-gray-900"><div class="mx-auto max-w-4xl p-8"><div class="flex justify-between border-b pb-5"><div><h1 class="text-3xl font-bold">INVOICE</h1><div>{{ $invoice->invoice_number }}</div></div><div class="text-right"><div>Date: {{ $invoice->invoice_date?->format('d-m-Y') }}</div><div>Reference: {{ $invoice->reference ?: '—' }}</div></div></div><div class="grid grid-cols-2 gap-8 py-6"><div><div class="font-bold">Bill To</div><div>{{ $invoice->customer->company_name }}</div><div class="whitespace-pre-line">{{ $invoice->customer->address }}</div><div>{{ $invoice->customer->phone ?: $invoice->customer->mobile }}</div></div><div><div class="font-bold">Summary</div><div>{{ $invoice->summary ?: '—' }}</div></div></div><table class="w-full border-collapse"><thead><tr class="border-y"><th class="p-2 text-left">Sr.</th><th class="p-2 text-left">Description</th><th class="p-2 text-right">Qty</th><th class="p-2 text-right">Unit Price</th><th class="p-2 text-right">Amount</th></tr></thead><tbody>@foreach($invoice->items as $item)<tr class="border-b"><td class="p-2">{{ $item->line_no }}</td><td class="p-2">{{ $item->description }}</td><td class="p-2 text-right">{{ rtrim(rtrim(number_format($item->quantity,4,'.',''), '0'), '.') }} {{ $item->unit }}</td><td class="p-2 text-right">PKR {{ number_format($item->selling_price_unit,2) }}</td><td class="p-2 text-right">PKR {{ number_format($item->selling_price_unit*$item->quantity-$item->discount+$item->tax_amount,2) }}</td></tr>@endforeach</tbody></table><div class="ml-auto mt-6 w-72 space-y-1"><div class="flex justify-between"><span>Subtotal</span><span>PKR {{ number_format($invoice->subtotal,2) }}</span></div><div class="flex justify-between"><span>Discount</span><span>PKR {{ number_format($invoice->discount_total,2) }}</span></div><div class="flex justify-between"><span>Tax</span><span>PKR {{ number_format($invoice->tax_total,2) }}</span></div><div class="flex justify-between border-t pt-2 text-lg font-bold"><span>Total PKR</span><span>{{ number_format($invoice->total_amount,2) }}</span></div></div>@if($invoice->terms)<div class="mt-8 border-t pt-4"><div class="font-bold">Terms & Conditions</div><div class="whitespace-pre-line">{{ $invoice->terms }}</div></div>@endif<div class="mt-16 flex justify-end"><div class="border-t px-10 pt-2 text-center">Authorized Signature</div></div><button onclick="window.print()" class="no-print fixed bottom-5 right-5 rounded bg-gray-900 px-5 py-2 text-white">Print</button></div></body></html>
